const $=x=>document.getElementById(x),cache={};let active=null,token=0;
const fmt=(x,n=2)=>x==null?'未知':Number(x).toLocaleString('zh-CN',{minimumFractionDigits:n,maximumFractionDigits:n});
$('pmodel').innerHTML=Object.entries(LABELS).map(([m,n])=>`<option value="${m}">${m} · ${n}</option>`).join('');$('pmodel').value='B1';$('prule').innerHTML=RULES.map(x=>`<option>${x}</option>`).join('');$('prule').value='F60';
async function shard(m){if(cache[m])return cache[m];const task=(async()=>{let enc;if(location.protocol==='file:'){await new Promise((ok,no)=>{let s=document.createElement('script');s.src=`data/performance_${m}.js`;s.onload=()=>{enc=window.PERFORMANCE_PAYLOAD;s.remove();ok()};s.onerror=no;document.head.append(s)});}else{const r=await fetch(`data/performance_${m}.js`);if(!r.ok)throw Error('账户曲线加载失败 '+r.status);const t=await r.text();enc=t.match(/PERFORMANCE_PAYLOAD\s*=\s*["']([A-Za-z0-9+/=]+)["']/)?.[1];}if(!enc)throw Error('账户曲线分片为空');const b=Uint8Array.from(atob(enc),c=>c.charCodeAt(0));return JSON.parse(await new Response(new Blob([b]).stream().pipeThrough(new DecompressionStream('gzip'))).text());})();cache[m]=task;try{return await task}catch(e){delete cache[m];throw e}}
function plot(el,vals,dates,h,color){const w=1080,l=62,r=18,t=20,b=35,lo=Math.min(0,...vals),hi=Math.max(0,...vals),pad=Math.max(1,(hi-lo)*.08),ylo=lo-pad,yhi=hi+pad;const X=i=>l+i/(Math.max(1,vals.length-1))*(w-l-r),Y=v=>t+(yhi-v)/(yhi-ylo)*(h-t-b);let z='';for(let j=0;j<5;j++){let v=ylo+(yhi-ylo)*j/4,y=Y(v);z+=`<line x1="${l}" y1="${y}" x2="${w-r}" y2="${y}" stroke="#e4eae8"/><text x="${l-8}" y="${y+4}" text-anchor="end">${v.toFixed(1)}%</text>`}z+=`<line x1="${l}" y1="${Y(0)}" x2="${w-r}" y2="${Y(0)}" stroke="#9bb1ad" stroke-dasharray="4 4"/>`;const pts=vals.map((v,i)=>`${X(i).toFixed(2)},${Y(v).toFixed(2)}`).join(' ');z+=`<polyline points="${l},${Y(0)} ${pts} ${w-r},${Y(0)}" fill="${color}" opacity=".08"/><polyline points="${pts}" fill="none" stroke="${color}" stroke-width="2"/>`;for(let j=0;j<=4;j++){let i=Math.round((vals.length-1)*j/4);z+=`<text x="${X(i)}" y="${h-9}" text-anchor="${j===0?'start':j===4?'end':'middle'}">${dates[i]}</text>`}el.innerHTML=z;el.onpointermove=e=>{const i=Math.max(0,Math.min(vals.length-1,Math.round(((e.clientX-el.getBoundingClientRect().left)/el.getBoundingClientRect().width*w-l)/(w-l-r)*(vals.length-1))));const row=active.equity[i];$('hover').textContent=`${row[0]} · 权益 ${fmt(row[1])}元 · 累计收益 ${fmt((row[1]/10000-1)*100)}% · 可用现金 ${fmt(row[2])}元 · 红利应收 ${fmt(row[3])}元`;}}
async function render(){let id=++token;window.PERFORMANCE_READY=false;$('load').textContent='正在读取本地权益账本…';try{let model=$('pmodel').value,rows=await shard(model);if(id!==token)return;active=rows.find(x=>x.summary.exit_rule===$('prule').value&&x.slots===+$('pslots').value&&x.summary.start===$('pstart').value);if(!active)throw Error('没有这个账户组合');const s=active.summary,e=active.equity,dates=e.map(x=>x[0]),ret=e.map(x=>(x[1]/10000-1)*100);let peak=10000;const dd=e.map(x=>{peak=Math.max(peak,x[1]);return(x[1]/peak-1)*100});const stats=[['累计经济收益',fmt(s.economic_return_scenario_pct)+'%'],['最大回撤',fmt(s.max_drawdown_scenario_pct)+'%'],['期末经济权益',fmt(e.at(-1)[1])+'元'],['已退出 / 仍持有',`${s.closed_trades} / ${s.open_positions}`],['已退出胜率',fmt(s.win_rate_pct)+'%'],['平均市场暴露',fmt(s.mean_exposure_pct)+'%'],['空仓天数比例',fmt(s.flat_pct)+'%']];$('pstats').innerHTML=stats.map(([n,v])=>`<div class="stat"><span>${n}</span><strong>${v}</strong></div>`).join('');plot($('equity'),ret,dates,350,'#15786d');plot($('drawdown'),dd,dates,190,'#b96737');$('load').textContent=`${model} · ${s.exit_rule} · 最多${active.slots}仓 · ${s.start}—${s.cutoff} · ${e.length}个交易日权益点`;$('hover').textContent=`将鼠标移到曲线上查看日期及现金。最后权益 ${fmt(e.at(-1)[1])}元。`;let d=DAILY.find(x=>x.model===model&&x.rule===s.exit_rule&&x.k===active.slots);$('daily').innerHTML=d?`<div class="stats">${[['计划累计预算',fmt(d.scheduled_budget_yuan)+'元'],['累计经济盈亏',fmt(d.net_pnl_yuan)+'元'],['盈亏 / 计划预算',fmt(d.pnl_over_scheduled_budget_pct)+'%'],['已成交 / 已退出 / 持有',`${d.filled} / ${d.closed} / ${d.open}`]].map(([n,v])=>`<div class="stat"><span>${n}</span><strong>${v}</strong></div>`).join('')}</div><p>批次汇总覆盖完整研究期，不受上方账户起点选择影响。已实现 ${fmt(d.realized_pnl_yuan)}元；未退出估值 ${fmt(d.marked_open_pnl_yuan)}元。</p>`:'无该批次汇总';window.PERFORMANCE_CURRENT={model,rule:s.exit_rule,slots:active.slots,start:s.start,last_date:e.at(-1)[0],equity_points:e.length,return_pct:s.economic_return_scenario_pct,max_drawdown_pct:s.max_drawdown_scenario_pct};window.PERFORMANCE_READY=true;}catch(e){$('load').textContent='读取失败：'+e.message;console.error(e)}}
for(const k of ['pmodel','prule','pslots','pstart'])$(k).onchange=render;$('download').onclick=()=>{if(!active)return;let a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeffdate,equity_yuan,return_pct,cash_yuan,dividend_receivable,bonus_receivable\n'+active.equity.map(r=>[r[0],r[1],(r[1]/10000-1)*100,...r.slice(2)].join(',')).join('\n')],{type:'text/csv;charset=utf-8'}));a.download=active.source.replace('.json','_equity.csv');a.click();setTimeout(()=>URL.revokeObjectURL(a.href),10000)};render();